package org.springframework.samples.petclinic.model;

import org.springframework.core.style.ToStringCreator;

import jakarta.persistence.*;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Pattern;

import java.time.LocalDate;
import java.util.*;

/**
 * Simple JavaBean domain object representing an owner.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
public class Owner extends Person {
    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "postcode")
    private String postcode;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
    private String telephone;

    @Column(name = "email")
    private String email;

    @Column(name = "registration_date")
    private LocalDate registrationDate;

    @Column(name = "birth_date")
    private LocalDate birthDate;

    @Column(name = "customer_code")
    private String customerCode;

    @Column(name = "membership_number")
    private String membershipNumber;

    @Column(name = "household_id")
    private String householdId;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Transient
    private Boolean bulkSignupWarning;

    @Transient
    private Boolean possibleDuplicate;

    @Transient
    private Integer possibleDuplicateOf;

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

    public String getAddress() {
        return this.address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getCity() {
        return this.city;
    }

    public void setCity(String city) {
        this.city = city;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    /**
     * Country code (without the leading {@code '+'}) to its national-number length, used to split the
     * stored E.164 {@link #getTelephone() telephone} into country code and national digits when
     * formatting {@link #getTelephoneDisplay()}. Mirrors the country codes recognized at creation
     * (see the telephone normalizer): {@code +61} has 9 national digits, {@code +1} has 10. Iterated
     * longest-code-first (hence {@link LinkedHashMap}) so a longer code wins over a shorter one that is
     * a prefix of the number.
     */
    private static final Map<String, Integer> TELEPHONE_NATIONAL_LENGTHS;
    static {
        Map<String, Integer> lengths = new LinkedHashMap<>();
        lengths.put("61", 9); // Australia
        lengths.put("1", 10); // North American Numbering Plan
        TELEPHONE_NATIONAL_LENGTHS = lengths;
    }

    /**
     * The stored {@link #getTelephone() telephone} formatted for humans: the country code (with its
     * leading {@code '+'}), a space, then the national digits grouped in threes (e.g.
     * {@code +61412345678} -> {@code +61 412 345 678}). The raw stored value is returned unchanged when
     * it is {@code null} or not a recognized E.164 number (a {@code '+'} and a known country code whose
     * national-number length matches). The raw {@link #getTelephone() telephone} stays in E.164 form.
     */
    public String getTelephoneDisplay() {
        if (this.telephone == null || !this.telephone.startsWith("+")) {
            return this.telephone;
        }
        String digits = this.telephone.substring(1);
        for (Map.Entry<String, Integer> entry : TELEPHONE_NATIONAL_LENGTHS.entrySet()) {
            String code = entry.getKey();
            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
                String national = digits.substring(code.length());
                StringBuilder grouped = new StringBuilder();
                for (int i = 0; i < national.length(); i += 3) {
                    if (grouped.length() > 0) {
                        grouped.append(' ');
                    }
                    grouped.append(national, i, Math.min(i + 3, national.length()));
                }
                return "+" + code + " " + grouped;
            }
        }
        return this.telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    /**
     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
     * (so the field is absent from the response) or the registration date is unknown.
     */
    public String getAgeBand() {
        if (this.birthDate == null || this.registrationDate == null) {
            return null;
        }
        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
        if (age < 18) {
            return "MINOR";
        }
        if (age < 65) {
            return "ADULT";
        }
        return "SENIOR";
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    public String getMembershipNumber() {
        return this.membershipNumber;
    }

    public void setMembershipNumber(String membershipNumber) {
        this.membershipNumber = membershipNumber;
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    /**
     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
     * have already been created for this owner's registration day. Computed per request, not persisted.
     */
    public Boolean getBulkSignupWarning() {
        return this.bulkSignupWarning;
    }

    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
        this.bulkSignupWarning = bulkSignupWarning;
    }

    /**
     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
     * telephone — a near match. Always false for an owner admitted as a declared household member (via
     * {@code sharesHousehold}), which is not a suspected duplicate.
     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
     */
    public Boolean getPossibleDuplicate() {
        return this.possibleDuplicate;
    }

    public void setPossibleDuplicate(Boolean possibleDuplicate) {
        this.possibleDuplicate = possibleDuplicate;
    }

